function sendInvoice(customer, amount) {
  const canAfford = customer.creditLimit >= amount;
  const isPriority = customer.openSupportTickets > 0;
  if (canAfford && !isPriority) {
    return `寄出 ${amount} 元的請款單`;
  }
  return '暫不寄出請款單';
}

console.log(sendInvoice({ creditLimit: 1000, openSupportTickets: 2 }, 500));

