function handleEvent(event) {
  if (event.type === 'OrderPlaced') {
    return `確認訂單 ${event.orderId}，通知倉庫準備出貨`;
  }
  if (event.type === 'OrderCancelled') {
    return `取消訂單 ${event.orderId}，釋放已保留的庫存`;
  }
  return '未知事件，忽略';
}

console.log(handleEvent({ type: 'OrderPlaced', orderId: 'A100' }));
console.log(handleEvent({ type: 'OrderCancelled', orderId: 'A100' }));

